#!/bin/sh
# SPDX-License-Identifier: MIT
#
# dnswatchd - writing the servers-file and reloading dnsmasq.
#
# The file always holds exactly one `server=` line. dnsmasq re-reads
# --servers-file on SIGHUP (man dnsmasq, option.c:read_servers_file), so a
# reload is enough and the whole dnsmasq config is never regenerated by us.

: "${DNSWATCHD_LIB:=/usr/lib/dnswatchd}"
# shellcheck source=/dev/null
. "$DNSWATCHD_LIB/common.sh"

# reload_dnsmasq prefers the init script: OpenWrt's reload runs start_service
# first, and procd may already be replacing the instance, so a raw `kill -HUP
# $(pidof dnsmasq)` can hit a dying PID (or two PIDs mid-restart).
reload_dnsmasq() {
	if [ -x "$DNSMASQ_INIT" ]; then
		if "$DNSMASQ_INIT" reload >/dev/null 2>&1; then
			return 0
		fi
		err "dnsmasq reload failed via $DNSMASQ_INIT"
		return 1
	fi

	_pid=$(pidof dnsmasq 2>/dev/null)
	if [ -z "$_pid" ]; then
		log "dnsmasq is not running; servers-file written but not reloaded"
		return 1
	fi

	# shellcheck disable=SC2086
	kill -HUP $_pid 2>/dev/null || {
		err "HUP dnsmasq (pid $_pid) failed"
		return 1
	}
	return 0
}

# write_servers_file <addr> <port>
# The file contents are the contract; reloading is a separate step so takeover
# can update the file and the dhcp config and then reload exactly once.
write_servers_file() {
	_addr=$1
	_port=${2:-53}
	_target=$_addr
	[ "$_port" != "53" ] && _target="$_addr#$_port"

	if [ "$DRY_RUN" = "1" ]; then
		log "DRY-RUN: would write 'server=$_target' to $SERVERS_FILE"
		return 0
	fi

	_dir=$(dirname "$SERVERS_FILE")
	mkdir -p "$_dir" 2>/dev/null || {
		err "cannot create $_dir"
		return 1
	}

	_tmp="$SERVERS_FILE.tmp.$$"
	if ! printf '# managed by dnswatchd - do not edit\nserver=%s\n' "$_target" > "$_tmp"; then
		err "cannot write $_tmp"
		rm -f "$_tmp"
		return 1
	fi

	if ! mv "$_tmp" "$SERVERS_FILE"; then
		err "cannot move $_tmp into place"
		rm -f "$_tmp"
		return 1
	fi

	# Read back before touching dnsmasq: never ask dnsmasq to reload a file we
	# are not sure about.
	_want="server=$_target"
	_got=$(sed -n 's/^server=//p' "$SERVERS_FILE" 2>/dev/null | head -1)
	if [ "server=$_got" != "$_want" ]; then
		err "servers-file verification failed (wanted '$_want', read 'server=$_got')"
		return 1
	fi

	return 0
}

# apply_upstream <addr> <port> — write, then make dnsmasq read it.
apply_upstream() {
	write_servers_file "$1" "$2" || return 1

	if ! reload_dnsmasq; then
		return 1
	fi

	log "applied: server=$( [ "${2:-53}" != "53" ] && printf '%s#%s' "$1" "$2" || printf '%s' "$1" ) -> $SERVERS_FILE"
	return 0
}
